    let m = trimmed.match(/^All Group\s*\((\d+)\)$/i);
    if (m) return lang === 'ar' ? `كل المجموعة (${m[1]})` : `Tout le Groupe (${m[1]})`;

    m = trimmed.match(/^(\d+)\s+Industries?\s*·\s*(\d+)\s+Companies(?:\s+Permitted)?\s*\(?RLS\)?$/i);
