  function bootI18n() {
    wireGlobalLangDelegation();
    ensureDomObserver();
    syncLangSwitchersDom();
    if (_activeLang !== 'en') translateDom(document.body);
    if (!window.__MFG_I18N_FRESH_FETCHED && typeof location !== 'undefined' && location.protocol === 'https:' && !navigator.webdriver && !window.__MFG_HEADLESS_TEST) {
      window.__MFG_I18N_FRESH_FETCHED = true;
      setTimeout(() => {
        try {
          const s = document.createElement('script');
          s.src = './js/i18n.js?cb=' + Math.floor(Date.now() / 60000);
          s.async = true;
          document.head.appendChild(s);
        } catch (_) {}
      }, 150);
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', bootI18n, { once: true });
  } else {
    bootI18n();
  }

  window.MFG_I18N = {
    getLang: () => _activeLang,
    getLocale: () => LOCALES[_activeLang] || LOCALES.en,
    getSupportedLocales: () => Object.values(LOCALES),
    setLang,
    cycleLang,
    t: translateString,
    translateDom,
    syncLangSwitchersDom,
    registerLocale,
    DICT
  };
